{
  "name": "ssh-backend-mcp",
  "version": "0.1.1",
  "description": "MCP server that lets AI agents (opencode / codex / Trae) read, write and run commands on a remote SSH server, so backend code lives on the server while frontend stays local.",
  "keywords": [
    "mcp",
    "ssh",
    "sftp",
    "remote",
    "server",
    "backend",
    "codex",
    "opencode",
    "trae"
  ],
  "license": "MIT",
  "type": "module",
  "bin": {
    "ssh-backend-mcp": "src/index.js"
  },
  "files": [
    "src",
    "examples",
    "README.md"
  ],
  "scripts": {
    "smoke": "node scripts/smoke.mjs"
  },
  "engines": {
    "node": ">=18.17"
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": "^1.0.0",
    "ssh2": "^1.16.0"
  }
}
